tool_input.script:
export const meta = { name: 'catacomb-echo', description: 'Echo words through workflow agents', phases: [{ title: 'Echo' }, { title: 'Report' }] }
const words = await parallel([
  () => agent('[catacomb:wf-left] Run `echo left` with the Bash tool and report its output.', { label: 'left', phase: 'Echo' }),
  () => agent('[catacomb:wf-right] Run `echo right` with the Bash tool and report its output.', { label: 'right', phase: 'Echo' }),
])
const report = await agent('[catacomb:wf-report] Run `echo report` with the Bash tool and report its output.', { label: 'report', phase: 'Report' })
return { words, report }
